using System.Windows;
using System.Windows.Data;
using System.Windows.Media;
using ASPAssistant.Core.Models;

namespace ASPAssistant.App;

/// <summary>
/// Six palettes: 终端 / 乌萨斯 / 可露希尔, each with a day and a night variant
/// (Resources/Themes/&lt;Theme&gt;.&lt;Light|Dark&gt;.xaml, generated by tools/gen_themes.py).
/// Brushes are live: switching copies colors into the brushes the UI already holds, so nothing re-renders
/// from scratch; non-brush resources (corner radii, number font) are replaced and picked up by DynamicResource.
/// </summary>
public static class ThemeManager
{
    private static readonly ResourceDictionary Palette = new()
    {
        Source = new Uri("/ASPAssistant.App;component/Resources/Themes/Terminal.Dark.xaml", UriKind.Relative)
    };
    private static readonly Dictionary<string, SolidColorBrush> ColorSources = new();

    static ThemeManager()
    {
        foreach (var key in Palette.Keys.Cast<string>().ToArray())
            if (Palette[key] is SolidColorBrush brush)
            {
                var source = brush.Clone();
                ColorSources.Add(key, source);
                var liveBrush = new SolidColorBrush();
                BindingOperations.SetBinding(liveBrush, SolidColorBrush.ColorProperty,
                    new Binding(nameof(SolidColorBrush.Color)) { Source = source, Mode = BindingMode.OneWay });
                Palette[key] = liveBrush;
            }
    }

    public static GameShopTheme Theme { get; private set; } = GameShopTheme.Terminal;
    public static bool IsNight { get; private set; } = true;
    public static bool IsLight => !IsNight;

    public static event Action? Changed;

    public static void Apply(GameShopTheme theme, bool night)
    {
        var name = theme switch { GameShopTheme.Ursus => "Ursus", GameShopTheme.Closure => "Closure", _ => "Terminal" };
        var colors = new ResourceDictionary
        {
            Source = new Uri($"/ASPAssistant.App;component/Resources/Themes/{name}.{(night ? "Dark" : "Light")}.xaml",
                UriKind.Relative)
        };
        foreach (string key in colors.Keys)
        {
            if (colors[key] is SolidColorBrush brush && ColorSources.TryGetValue(key, out var source))
                source.Color = brush.Color;
            else
                Palette[key] = colors[key];
        }
        Application.Current.Resources.MergedDictionaries[0] = Palette;
        Theme = theme;
        IsNight = night;
        Changed?.Invoke();
    }
}
